package io.github.jesterportfolio.hearth.phone;

import com.google.gson.*;
import io.github.jesterportfolio.hearth.quest.GameInformation;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

/** 네 논리 Chat의 두 동시 요청을 고정 예산으로 확인합니다. 실제 Minecraft 동접/PG 부하나 GPU 취소의 증명이 아닙니다. */
public final class OllamaConcurrentProbe {
    private static PhoneGrounding.Plan plan(int index){String colour=List.of("청색","황색","흑색","백색").get(index);var data=new GameInformation(List.of(),List.of(),List.of(new GameInformation.Diary("PERSON","공개 시험 기록","표식", "이 기록의 표식은 "+colour+"이다.",false)),List.of());var item=new PhoneHelp.Selection("diary","synthetic_"+index,data,new PhoneRetrieval.Source("diary",index,"공개 시험 기록","이 기록의 표식은 "+colour+"이다."));return new PhoneGrounding.Plan("diary","자료의 표식 한 단어와 [자료 1]만 답해.",false,List.of(new PhoneGrounding.Material(item,1,-1)),Set.of(item.key()));}
    private static CompletionStage<Void> send(PhoneChat chat,PhoneGrounding.Plan plan){return chat.submitGroundedPreview(chat.previewGrounded(plan),plan,()->true,()->CompletableFuture.completedFuture(true));}
    private static String answer(ExecutorService owner,PhoneChat chat)throws Exception{return owner.submit(()->chat.history().getLast().answer()).get();}
    private static void row(JsonArray rows,String name,boolean pass){var value=new JsonObject();value.addProperty("name",name);value.addProperty("outcome",pass?"PASS":"QUALITY_REVIEW_REQUIRED");rows.add(value);}
    public static void main(String[] args)throws Exception{
        if(args.length!=2||!args[0].equals("http://127.0.0.1:11435/api/generate"))throw new IllegalArgumentException("TRIAL_ENDPOINT");var owner=Executors.newSingleThreadExecutor();var metrics=new PhoneTelemetry();var report=new JsonObject();var rows=new JsonArray();var sent=Collections.synchronizedList(new ArrayList<AssistantRequest>());
        try(var backend=new MeasuredAssistant(new OllamaAssistant(args[0]))){
            backend.prepare().toCompletableFuture().get(85,TimeUnit.SECONDS);var service=new AssistantService(){public boolean allowsCache(){return true;}public CompletionStage<String> ask(String q){throw new AssertionError();}public CompletionStage<String> ask(AssistantRequest request){sent.add(request);return backend.ask(request);}public CompletionStage<String> confirmCached(String answer){return backend.confirmCached(answer);}};
            var chats=owner.submit(()->java.util.stream.IntStream.range(0,4).mapToObj(i->new PhoneChat(service,owner,metrics)).toList()).get();owner.submit(()->chats.get(0).includeHistory(false)).get();
            owner.submit(()->send(chats.get(0),plan(0))).get().toCompletableFuture().get(8,TimeUnit.SECONDS);String baseline=answer(owner,chats.get(0));row(rows,"prepared_sequential_baseline",baseline.contains("청색")&&baseline.contains("[자료 1]"));
            long[] started=new long[2],ended=new long[2];var jobs=owner.submit(()->{var result=new ArrayList<CompletableFuture<Void>>();for(int i=0;i<2;i++){int n=i;started[n]=System.nanoTime();var work=send(chats.get(n+1),plan(n+1)).toCompletableFuture();result.add(work.whenComplete((v,e)->ended[n]=System.nanoTime()));}return result;}).get();CompletableFuture.allOf(jobs.toArray(CompletableFuture[]::new)).get(9,TimeUnit.SECONDS);boolean overlap=Math.max(started[0],started[1])<Math.min(ended[0],ended[1]);String first=answer(owner,chats.get(1)),second=answer(owner,chats.get(2));row(rows,"two_overlapping_requests_both_accepted_and_isolated",overlap&&first.contains("황색")&&!first.contains("흑색")&&second.contains("흑색")&&!second.contains("황색"));
            report.add("concurrent_answers",new Gson().toJsonTree(List.of(first,second)));report.add("concurrent_elapsed_ms",new Gson().toJsonTree(List.of((ended[0]-started[0])/1_000_000,(ended[1]-started[1])/1_000_000)));report.addProperty("logical_request_intervals_overlap",overlap);
            boolean cancelled=owner.submit(()->{var work=send(chats.get(3),plan(3)).toCompletableFuture();chats.get(3).cancel();return work.isCancelled()&&!chats.get(3).busy()&&chats.get(3).history().isEmpty()&&chats.get(3).draft().equals(plan(3).question());}).get();row(rows,"cancel_preserves_draft_and_rejects_late_acceptance",cancelled);
            owner.submit(()->send(chats.get(3),plan(3))).get().toCompletableFuture().get(8,TimeUnit.SECONDS);String recovery=answer(owner,chats.get(3));row(rows,"new_question_after_cancel",recovery.contains("백색")&&recovery.contains("[자료 1]"));
            long generated=backend.snapshot().usage().getFirst().started();owner.submit(()->send(chats.get(0),plan(0))).get().toCompletableFuture().get(8,TimeUnit.SECONDS);row(rows,"cache_is_accepted_without_new_generation",backend.snapshot().usage().getFirst().started()==generated&&answer(owner,chats.get(0)).equals(baseline));
            var previous=owner.submit(chats.get(0)::history).get();boolean rejected=false;try{owner.submit(()->chats.get(0).submitGroundedPreview(chats.get(0).previewGrounded(plan(0)),plan(0),()->true,()->CompletableFuture.completedFuture(false))).get().toCompletableFuture().get(8,TimeUnit.SECONDS);}catch(ExecutionException expected){rejected=String.valueOf(expected.getCause().getMessage()).contains("STALE_AI_CONTEXT");}
            row(rows,"cached_result_requires_validation_and_keeps_history",rejected&&backend.snapshot().usage().getFirst().started()==generated&&owner.submit(()->chats.get(0).history().equals(previous)&&chats.get(0).cacheStats().entries()==0&&!chats.get(0).draft().isBlank()).get());
            owner.submit(()->chats.forEach(PhoneChat::close)).get();var snapshot=metrics.snapshot();boolean counts=snapshot.timings().stream().allMatch(t->t.active()==0)&&snapshot.outcomes().get(PhoneTelemetry.Outcome.ACCEPTED)==4&&snapshot.outcomes().get(PhoneTelemetry.Outcome.CACHED)==1&&snapshot.outcomes().get(PhoneTelemetry.Outcome.CANCELLED)==1&&snapshot.outcomes().get(PhoneTelemetry.Outcome.VALIDATION_FAILED)==1;row(rows,"stage_and_terminal_counts_are_separate_and_closed",counts);row(rows,"no_internal_scope_keys_in_model_payload",sent.stream().allMatch(r->r.sources()==1&&!r.prompt().contains("synthetic_")));
            boolean passed=true;for(var value:rows)passed&=value.getAsJsonObject().get("outcome").getAsString().equals("PASS");report.add("flow_telemetry",new Gson().toJsonTree(snapshot));report.add("backend_usage",new Gson().toJsonTree(backend.snapshot()));report.add("cases",rows);report.addProperty("required_checks_passed",passed);report.addProperty("real_model",true);report.addProperty("actual_minecraft_client",false);report.addProperty("four_player_capacity_pass",false);report.addProperty("mixed_paper_pg_ai_load",false);Files.writeString(Path.of(args[1]),new GsonBuilder().setPrettyPrinting().create().toJson(report)+"\n");System.out.println("HEARTH_S5_CONCURRENT_PROBE_FINISHED pass="+passed);
        }finally{owner.shutdownNow();owner.awaitTermination(2,TimeUnit.SECONDS);}
    }
}
